diff --git a/eval/README.md b/eval/README.md
index 0b1449b6..09574bef 100644
--- a/eval/README.md
+++ b/eval/README.md
@@ -358,3 +358,11 @@ Deviations from §9, recorded before the run: fixture tasks rather than external
 only (no T3/T4 — the window is too short); Codex CLI excluded (the gateway does not serve `/v1/responses`); Aider runs
 one `--message` exchange with `--yes-always` (its non-interactive mode); no cloud configuration (operator decision);
 runs per task as many as the window allows, run-major, target 5.
+
+### Code-evaluator commands and `prlimit`
+
+`build` and `typecheck_clean` commands run in Bubblewrap behind `/usr/bin/prlimit` (util-linux), which caps a single file write
+(`maxFileBytes`, default 1 GiB, settable per evaluator spec) and disables core dumps. The evaluator refuses to run a command
+without it, so `eval/host/provision.sh` stops and `eval/host/validate.mjs` fails on a host where it is missing or unusable.
+Memory, process-count, CPU and total-disk limits come only from the resource contract above (`config.resources`); a run
+without one has the per-file cap but no cgroup budget for these commands.
diff --git a/eval/check_phase.mjs b/eval/check_phase.mjs
new file mode 100644
index 00000000..3e4bb766
--- /dev/null
+++ b/eval/check_phase.mjs
@@ -0,0 +1,14 @@
+/**
+ * The post-agent phase of one run, in the only order that keeps the candidate workspace the agent's own.
+ *
+ * The code evaluators discover changed paths by comparing the candidate workspace with the pre-agent snapshot, and the
+ * build/typecheck evaluators copy it. In a non-hardened run the hidden check stages its tests into that workspace and the
+ * regression check writes caches there, so the evaluators must finish first or diff_boundary counts the harness's own files
+ * as agent changes. Each step is passed in as a function so the ordering can be tested without the sandbox fixtures.
+ */
+export async function runPostAgentPhase({ evaluators, hidden, regression }) {
+  const evaluatorResults = await evaluators();
+  const hiddenResult = await hidden();
+  const regressionResult = await regression();
+  return { evaluators: evaluatorResults, hidden: hiddenResult, regression: regressionResult };
+}
